def get_running_tasks(time, window):
    node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(node)
    running = []
    for i, row in rows:
        t = int(row['time'])
        if t > time:
            break
        if row['event'] == 'start':
            task_id = row['task']
            # find if it finished or was evicted/failed
            finished = False
            for j, row2 in rows:
                if j <= i: continue
                if row2['task'] == task_id and row2['event'] in ['finish', 'evict', 'fail']:
                    if int(row2['time']) <= time:
                        finished = True
                    break
            if not finished:
                running.append(row)
    return running

