def get_tasks_running_at(window, time):
    log = table_rows(node_by_title(doc, f"{window}: Task log"))
    running = set()
    for row_idx, row in log:
        t = int(row['time'])
        if t > time:
            break
        task = row['task']
        event = row['event']
        if event == 'start':
            running.add(task)
        elif event in ['finish', 'evict', 'fail']:
            running.discard(task)

    # Now get the details for these tasks to see their machine and resources
    details = {}
    for row_idx, row in log:
        task = row['task']
        if task in running:
            # The last event for this task before or at 'time' that specifies the machine
            # Actually, the task log records 'start' with the machine.
            if row['event'] == 'start':
                details[task] = row
    return details

