def get_queue_at(window, time):
    log = table_rows(node_by_title(doc, f"{window}: Task log"))
    submitted = set()
    started = set()
    finished = set()

    # We need to simulate to be sure, but let's just see who was submitted and not yet started/finished
    for row_idx, row in log:
        t = int(row['time'])
        if t > time:
            break
        task = row['task']
        if row['event'] == 'submit':
            submitted.add(task)
        elif row['event'] == 'start':
            started.add(task)
        elif row['event'] in ['finish', 'evict', 'fail']:
            finished.add(task)

    return submitted - started

