def get_status_at_time(doc, time):
    machines = {}
    log_node = node_by_title(doc, 'Cell window 02: Task log')

    # Initialize machines
    mach_node = node_by_title(doc, 'Cell window 02: Machines')
    for row in table_rows(mach_node):
        r = row[1]
        machines[r['machine']] = {
            'cpu': int(r['CPU']),
            'mem': int(r['memory']),
            'tasks': set(),
            'up': True
        }

    # Process log
    for row in table_rows(log_node):
        r = row[1]
        t = int(r['time'])
        if t > time: break

        # Machine failures/returns are in the Events section, not the Task log
        # But the Task log has 'fail' events for tasks.
        # Let's also check the Events section for machine status.

        if r['event'] == 'start':
            machines[r['machine']]['tasks'].add(r['task'])
        elif r['event'] in ['finish', 'evict', 'fail']:
            machines[r['machine']]['tasks'].discard(r['task'])

    # Now we need to adjust machine 'up' status from Events
    events_node = node_by_title(doc, 'Cell window 02: Events')
    for line in events_node['lines']:
        if 'machine' in line and 'failed' in line:
            # Example: "Time 389: machine M01 failed"
            m_id = line.split('machine ')[1].split(' failed')[0]
            if int(line.split(': ')[0].split(' ')[1]) <= time:
                machines[m_id]['up'] = False
        if 'machine' in line and 'returned' in line:
            # This isn't in the events for this window probably, check Machines table
            pass

    # Also check Machines table for fails_at and returns_at
    for row in table_rows(mach_node):
        r = row[1]
        m_id = r['machine']
        fail_at = r['fails at']
        ret_at = r['returns at']
        if fail_at != '-' and int(fail_at) <= time:
            if ret_at == '-' or int(ret_at) > time:
                machines[m_id]['up'] = False
        if ret_at != '-' and int(ret_at) <= time:
            machines[m_id]['up'] = True

    return machines

