def get_cluster_state_at(doc, window, time):
    task_log_node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(task_log_node)

    machines_node = node_by_title(doc, f"{window}: Machines")
    machines_rows = table_rows(machines_node)
    machines = {}
    for idx, row in machines_rows:
        machines[row['machine']] = {
            'cpu': int(row['CPU']),
            'mem': int(row['memory']),
            'fail': row['fails at'] if row['fails at'] != '-' else None,
            'return': row['returns at'] if row['returns at'] != '-' else None
        }

    running_tasks = {} # task_id: (machine, cpu, mem, end_time)

    # Process events up to time
    for idx, row in rows:
        t = int(row['time'])
        if t > time:
            break

        task_id = row['task']
        event = row['event']
        machine = row['machine']

        if event == 'start':
            cpu = int(row['CPU'])
            mem = int(row['memory'])
            run_time = int(row['run time'])
            running_tasks[task_id] = (machine, cpu, mem, t + run_time)
        elif event == 'finish':
            if task_id in running_tasks:
                del running_tasks[task_id]
        elif event == 'evict' or event == 'fail':
            if task_id in running_tasks:
                del running_tasks[task_id]

    # Check machine failures
    for m_id, m_info in machines.items():
        if m_info['fail'] and int(m_info['fail']) <= time:
            # If it hasn't returned by 'time', it's down
            if m_info['return'] is None or int(m_info['return']) > time:
                # All tasks on this machine should be gone (already handled by 'fail' events in log)
                pass

    return running_tasks, machines

