        if machine_failure_override and m_id == machine_failure_override['machine']:
            fails_at = machine_failure_override['fails_at']

        machines_state[m_id] = {
            'cpu_cap': int(m['CPU']),
            'mem_cap': int(m['memory']),
            'cpu_free': int(m['CPU']),
            'mem_free': int(m['memory']),
            'up': True,
            'fails_at': fails_at,
            'returns_at': int(m['returns at']) if m['returns at'] != '-' else None,
            'tasks': {} # task_id -> finish_time
        }

    queue = [] # list of (priority, submit_time, task_id)

    # All unique times from the log and machines
    times = set()
    for row in t_data:
        times.add(int(row['time']))
    for m in m_data:
        if m['fails at'] != '-': times.add(int(m['fails at']))
        if m['returns at'] != '-': times.add(int(m['returns at']))

    sorted_times = sorted(list(times))

    for t in sorted_times:
        if t > target_time: break

        # 1. Finishes
        for m_id in machines_state:
            m = machines_state[m_id]
            finished = [t_id for t_id, f_time in m['tasks'].items() if f_time == t]
            for t_id in finished:
                req = task_reqs[t_id]
                m['cpu_free'] += req['cpu']
                m['mem_free'] += req['mem']
                del m['tasks'][t_id]

        # 2. Failures
        for m_id, m in machines_state.items():
            if m['fails_at'] == t:
                m['up'] = False
                # Tasks fail
                for t_id in list(m['tasks'].keys()):
                    # Task goes back to queue
                    # Original submission time is needed
                    submit_time = next(int(r['time']) for r in t_data if r['task'] == t_id and r['event'] == 'submit')
                    priority = task_reqs[t_id]['priority']
                    queue.append((priority, submit_time, t_id))
                    # Task ID for queue order
                    # The actual queue order is priority (desc), submit_time (asc), task_id (asc)
                m['tasks'] = {}
                m['cpu_free'] = 0
                m['mem_free'] = 0

        # 3. Returns
        for m_id, m in machines_state.items():
            if m['returns_at'] == t:
                m['up'] = True
                m['cpu_free'] = m['cpu_cap']
                m['mem_free'] = m['mem_cap']

