def get_queue_at_time(time):
    node = node_by_title(doc, "Cell window 23: Task log")
    rows = table_rows(node)

    machines = {
        'M01': {'cpu': 6250, 'mem': 3116},
        'M02': {'cpu': 6250, 'mem': 6244},
        'M03': {'cpu': 6250, 'mem': 6244},
        'M04': {'cpu': 6250, 'mem': 6244},
        'M05': {'cpu': 6250, 'mem': 6244},
        'M06': {'cpu': 6250, 'mem': 6244},
        'M07': {'cpu': 6250, 'mem': 6244},
        'M08': {'cpu': 6250, 'mem': 3116},
    }

    # Machine failures/returns
    fail_times = {'M04': 416}
    return_times = {'M04': 824}

    running_tasks = {} # task_id: (machine, end_time, cpu, mem)
    queue = [] # list of task_ids
    task_info = {} # task_id: {priority, cpu, mem, run_time, submit_time}

    # Filter logs up to the specified time
    for idx, row in rows:
        t = int(row['time'])
        if t > time:
            break

        # The scheduling policy steps happen at each time t.
        # But we just want the state *at* time t.
        # The logs already follow the policy.

        event = row['event']
        tid = row['task']

        if event == 'submit':
            task_info[tid] = {
                'priority': int(row['priority']),
                'cpu': int(row['CPU']),
                'mem': int(row['memory']),
                'run_time': int(row['run time']),
                'submit_time': t
            }
            queue.append(tid)
        elif event == 'start':
            machine = row['machine']
            running_tasks[tid] = (machine, t + task_info[tid]['run_time'], task_info[tid]['cpu'], task_info[tid]['mem'])
            if tid in queue:
                queue.remove(tid)
        elif event == 'finish':
            if tid in running_tasks:
                del running_tasks[tid]
        elif event == 'evict':
            if tid in running_tasks:
                del running_tasks[tid]
            queue.append(tid)
        elif event == 'fail':
            # Tasks on failed machine go back to queue
            for rid, (rmach, rend, rcpu, rmem) in list(running_tasks.items()):
                if rmach == row['machine']:
                    queue.append(rid)
                    del running_tasks[rid]

    return queue, running_tasks

