def get_tasks_on_machine_at_time(machine_id, time):
    running = set()
    node = node_by_title(doc, 'Cell window 26: Task log')
    rows = table_rows(node)
    for idx, row in rows:
        t = int(row['time'])
        if t > time:
            break
        if row['machine'] == machine_id:
            if row['event'] == 'start':
                running.add(row['task'])
            elif row['event'] in ['finish', 'evict', 'fail']:
                running.discard(row['task'])
    return running

