def get_task_info(chapter, job_id=None, task_ids=None):
    task_log_node = node_by_title(doc, f"{chapter}: Task log")
    rows = table_rows(task_log_node)
    tasks = {}
    for row_idx, row in rows:
        time = int(row['time'])
        task = row['task']
        job = row['job']
        priority = int(row['priority'])
        cpu = int(row['CPU'])
        mem = int(row['memory'])
        run_time = int(row['run time'])
        event = row['event']
        machine = row['machine']

        if task not in tasks:
            tasks[task] = {'job': job, 'priority': priority, 'cpu': cpu, 'mem': mem, 'run_time': run_time, 'submit_time': time}

        if job_id and job == job_id:
            if task not in tasks:
                tasks[task] = {'job': job, 'priority': priority, 'cpu': cpu, 'mem': mem, 'run_time': run_time, 'submit_time': time}

        if task_ids and task in task_ids:
            if task not in tasks:
                tasks[task] = {'job': job, 'priority': priority, 'cpu': cpu, 'mem': mem, 'run_time': run_time, 'submit_time': time}

    if job_id:
        return {t: info for t, info in tasks.items() if info['job'] == job_id}
    if task_ids:
        return {t: info for t, info in tasks.items() if t in task_ids}
    return tasks

